SELECT CAST(COUNT(CASE WHEN "sex" = 'male' THEN 1 END) AS FLOAT) / NULLIF(COUNT(CASE WHEN "sex" = 'female' THEN 1 END), 0) AS male_female_ratio
FROM "Patient"
WHERE "uric_acid" > 7.0 OR "uric_acid" < 3.5;

SELECT "patient_id", "uric_acid_value", "normal_range"
FROM "Patient"
WHERE "patient_id" = 57266;
